/**
 * Turns forge's MockTgbp artifact into a typed TypeScript module, so tests
 * need anvil but not a Solidity compiler. Run via `pnpm build:fixtures`.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const artifact = JSON.parse(
  readFileSync(new URL('../test/fixtures/out/MockTgbp.sol/MockTgbp.json', import.meta.url), 'utf8'),
) as { abi: unknown[]; bytecode: { object: string } }

const out = fileURLToPath(new URL('../test/fixtures/mock-tgbp.ts', import.meta.url))
writeFileSync(
  out,
  [
    '// GENERATED by scripts/export-fixture.ts from test/fixtures/MockTgbp.sol. Do not edit.',
    `export const mockTgbpAbi = ${JSON.stringify(artifact.abi, null, 2)} as const`,
    '',
    `export const mockTgbpBytecode = '${artifact.bytecode.object}' as const`,
    '',
  ].join('\n'),
)
console.log(`Wrote ${out}`)
